import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Link } from 'react-router-dom';
import {
  CurrencyDollarIcon,
  ClipboardDocumentListIcon,
  CheckCircleIcon,
  ClockIcon,
  TrophyIcon,
  ArrowRightIcon
} from '@heroicons/react/24/outline';
import { fetchMySubmissions } from '../../store/slices/taskSlice';
import { fetchWallet } from '../../store/slices/walletSlice';
import Card from '../../components/ui/Card';
import Badge from '../../components/ui/Badge';
import Button from '../../components/ui/Button';
import MobileNav from '../../components/layout/MobileNav';

const WorkerDashboard = () => {
  const dispatch = useDispatch();
  const { user, profile } = useSelector((state) => state.auth);
  const { mySubmissions } = useSelector((state) => state.tasks);
  const { wallet } = useSelector((state) => state.wallet);

  useEffect(() => {
    if (user?.id) {
      dispatch(fetchMySubmissions(user.id));
      dispatch(fetchWallet(user.id));
    }
  }, [dispatch, user?.id]);

  const stats = [
    {
      title: 'Available Balance',
      value: `$${wallet.balance?.toFixed(2) || '0.00'}`,
      icon: CurrencyDollarIcon,
      color: 'text-success-600',
      bgColor: 'bg-success-100'
    },
    {
      title: 'Total Earned',
      value: `$${wallet.totalEarned?.toFixed(2) || '0.00'}`,
      icon: TrophyIcon,
      color: 'text-primary-600',
      bgColor: 'bg-primary-100'
    },
    {
      title: 'Tasks Completed',
      value: profile?.tasks_completed || 0,
      icon: CheckCircleIcon,
      color: 'text-info-600',
      bgColor: 'bg-info-100'
    },
    {
      title: 'Pending Submissions',
      value: mySubmissions?.filter(s => s.status === 'pending').length || 0,
      icon: ClockIcon,
      color: 'text-warning-600',
      bgColor: 'bg-warning-100'
    }
  ];

  const recentSubmissions = mySubmissions?.slice(0, 5) || [];

  const getStatusBadge = (status) => {
    const variants = {
      pending: 'warning',
      under_review: 'info',
      approved: 'success',
      rejected: 'error',
      revision_requested: 'warning'
    };
    return variants[status] || 'default';
  };

  const getStatusText = (status) => {
    const texts = {
      pending: 'Pending Review',
      under_review: 'Under Review',
      approved: 'Approved',
      rejected: 'Rejected',
      revision_requested: 'Revision Requested'
    };
    return texts[status] || status;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-primary-50/30 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-12">
          <div className="flex items-center space-x-4 mb-4">
            <div className="w-16 h-16 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-2xl flex items-center justify-center shadow-xl">
              <span className="text-white text-2xl font-bold">
                {profile?.full_name?.charAt(0) || 'W'}
              </span>
            </div>
            <div>
              <h1 className="text-4xl font-black text-secondary-900">
                Welcome back, {profile?.full_name || 'Worker'}!
              </h1>
              <p className="text-secondary-600 mt-2 text-lg">
                Here's your activity overview and recent submissions
              </p>
            </div>
          </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {stats.map((stat, index) => (
            <Card key={index} className="hover:shadow-md transition-shadow duration-200">
              <div className="flex items-center">
                <div className={`w-12 h-12 ${stat.bgColor} rounded-lg flex items-center justify-center`}>
                  <stat.icon className={`w-6 h-6 ${stat.color}`} />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-secondary-600">{stat.title}</p>
                  <p className="text-2xl font-bold text-secondary-900">{stat.value}</p>
                </div>
              </div>
            </Card>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Recent Submissions */}
          <div className="lg:col-span-2">
            <Card>
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold text-secondary-900">Recent Submissions</h2>
                <Link
                  to="/my-submissions"
                  className="text-primary-600 hover:text-primary-500 font-medium text-sm flex items-center"
                >
                  View All
                  <ArrowRightIcon className="w-4 h-4 ml-1" />
                </Link>
              </div>

              {recentSubmissions.length > 0 ? (
                <div className="space-y-4">
                  {recentSubmissions.map((submission) => (
                    <div key={submission.id} className="border border-secondary-200 rounded-lg p-4 hover:bg-secondary-50 transition-colors">
                      <div className="flex items-center justify-between mb-2">
                        <h3 className="font-semibold text-secondary-900">
                          {submission.task?.title}
                        </h3>
                        <Badge variant={getStatusBadge(submission.status)}>
                          {getStatusText(submission.status)}
                        </Badge>
                      </div>
                      <div className="flex items-center justify-between text-sm text-secondary-600">
                        <span>Reward: ${submission.task?.reward_amount}</span>
                        <span>Submitted: {new Date(submission.submitted_at).toLocaleDateString()}</span>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <ClipboardDocumentListIcon className="w-12 h-12 text-secondary-400 mx-auto mb-4" />
                  <p className="text-secondary-600 mb-4">No submissions yet</p>
                  <Button>
                    <Link to="/tasks">Browse Available Tasks</Link>
                  </Button>
                </div>
              )}
            </Card>
          </div>

          {/* Quick Actions */}
          <div className="space-y-6">
            <Card>
              <h3 className="text-lg font-semibold text-secondary-900 mb-4">Quick Actions</h3>
              <div className="space-y-3">
                <Button className="w-full justify-start" variant="outline">
                  <Link to="/tasks" className="flex items-center">
                    <ClipboardDocumentListIcon className="w-5 h-5 mr-2" />
                    Browse Tasks
                  </Link>
                </Button>
                <Button className="w-full justify-start" variant="outline">
                  <Link to="/wallet" className="flex items-center">
                    <CurrencyDollarIcon className="w-5 h-5 mr-2" />
                    Manage Wallet
                  </Link>
                </Button>
                <Button className="w-full justify-start" variant="outline">
                  <Link to="/profile" className="flex items-center">
                    <TrophyIcon className="w-5 h-5 mr-2" />
                    Update Profile
                  </Link>
                </Button>
              </div>
            </Card>

            {/* Profile Completion */}
            <Card>
              <h3 className="text-lg font-semibold text-secondary-900 mb-4">Profile Strength</h3>
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-secondary-600">Profile Photo</span>
                  <CheckCircleIcon className="w-5 h-5 text-success-500" />
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-secondary-600">Skills Listed</span>
                  <CheckCircleIcon className="w-5 h-5 text-success-500" />
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-secondary-600">Account Status</span>
                  <CheckCircleIcon className="w-5 h-5 text-success-500" />
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-secondary-600">Profile Complete</span>
                  <CheckCircleIcon className="w-5 h-5 text-success-500" />
                </div>
              </div>
              <div className="mt-4">
                <div className="bg-secondary-200 rounded-full h-2">
                  <div className="bg-primary-600 h-2 rounded-full" style={{ width: '75%' }}></div>
                </div>
                <p className="text-sm text-secondary-600 mt-2">75% Complete</p>
              </div>
            </Card>
          </div>
        </div>
      </div>
      
      {/* Mobile Navigation */}
      <MobileNav />
    </div>
  );
};

export default WorkerDashboard;
